import{_ as s,o as e,c as i,a0 as t}from"./chunks/framework.BxCN1dRw.js";const k=JSON.parse('{"title":"跟做：双语公开站点","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/public-site"},"headers":[],"relativePath":"tutorials/public-site.md","filePath":"tutorials/public-site.md"}'),o={name:"tutorials/public-site.md"};function n(l,a,d,p,h,c){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="跟做-双语公开站点" tabindex="-1">跟做：双语公开站点 <a class="header-anchor" href="#跟做-双语公开站点" aria-label="Permalink to &quot;跟做：双语公开站点&quot;">​</a></h1><p>公开站点由 Landing、Documentation、Blog、Downloads 四部分组成：未登录的访客从简洁的品牌首页理解模板，从顶栏进入对应语言的文档，Blog 与 Downloads 保留稳定入口并如实显示&quot;即将推出&quot;。本章先从访客视角走一遍四类入口，再从维护者视角说明页面如何声明、文案如何保持真实、示例展示如何随示例移除，以及语言、主题与部署 base 的规则。</p><h2 id="_1-先体验-四类入口与公开路径" tabindex="-1">1. 先体验：四类入口与公开路径 <a class="header-anchor" href="#_1-先体验-四类入口与公开路径" aria-label="Permalink to &quot;1. 先体验：四类入口与公开路径&quot;">​</a></h2><p>构建并浏览站点：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 渲染双语站点并验证内置导航</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 本地开发服务器，边改边看</span></span></code></pre></div><p>中文入口在根路径：<code>/</code>（Landing）、<code>/docs/</code>（文档教程）、<code>/blog/</code>、<code>/downloads/</code>；英文一一对应到 <code>/en/</code> 下。语言由路径决定：访问 <code>/en/blog/</code> 得到英文页，站点不做设备语言重定向；顶栏的「English / 中文」按 frontmatter 里的对应页切换，永远落在已存在的页面上。旧章节深链（如 <code>/getting-started/quickstart</code>）不受改版影响。</p><h2 id="_2-信息结构-借鉴-expo-的四段式" tabindex="-1">2. 信息结构：借鉴 Expo 的四段式 <a class="header-anchor" href="#_2-信息结构-借鉴-expo-的四段式" aria-label="Permalink to &quot;2. 信息结构：借鉴 Expo 的四段式&quot;">​</a></h2><p>Landing 遵循 Expo 首页的信息结构，但只陈述真实交付的能力：</p><ol><li><strong>价值主张 + 主要动作</strong>：一句话说清模板（README 同款），主按钮进入当前语言的 Documentation，附 GitHub 仓库入口。</li><li><strong>使用流程</strong>：启动全栈 → 跟做教程 → 组合/移除示例 → 部署备份，每步链接到真实章节。</li><li><strong>真实能力</strong>：每张能力卡都链接到已有教程章节或 v1 覆盖页；没有&quot;规划中/即将支持&quot;的能力卡。</li><li><strong>结束 CTA</strong>：回到文档入口。</li></ol><p>写新卡片时的纪律：先确认能力在 <a href="./../architecture/v1-coverage">v1 覆盖与验收</a> 里有对应行，再决定卡片与链接；描述措辞与对应章节保持一致，不发明数字（性能、规模、用户量）。</p><h2 id="_3-页面如何声明-site-json-与渲染器" tabindex="-1">3. 页面如何声明：site.json 与渲染器 <a class="header-anchor" href="#_3-页面如何声明-site-json-与渲染器" aria-label="Permalink to &quot;3. 页面如何声明：site.json 与渲染器&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/docs/site.json" target="_blank" rel="noreferrer">site.json</a> 是唯一声明处。Landing 与两张占位页是带 <code>layout: &quot;page&quot;</code> 的普通页面条目：双语成对（<code>sourceEn</code>/<code>titleEn</code>），并携带成对的 <code>pageTitle</code>/<code>pageTitleEn</code> 与 <code>pageDescription</code>/<code>pageDescriptionEn</code>——渲染器把它们写进页面 frontmatter，页面 <code>&lt;title&gt;</code> 与 meta description 因此如实反映&quot;即将推出&quot;。校验在 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/scripts/lib/docs-locales.mjs" target="_blank" rel="noreferrer">docs-locales.mjs</a>：meta 必须成对、只能出现在 layout 页上，漏一半直接构建失败。</p><p>layout 页不进侧栏（渲染器同时写入 <code>sidebar: false</code>），只出现在顶栏；四类页面共用同一导航、页脚、视觉 tokens 与明暗规则。Landing 源文件是普通 Markdown 加受限 HTML（<code>docs/index.md</code> 与相邻的 <code>docs/index.en.md</code>），样式在 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/apps/docs/.vitepress/theme/custom.css" target="_blank" rel="noreferrer">custom.css</a> 里使用与文档一致的 <code>--vp-*</code> tokens。</p><h2 id="_4-coming-soon-的边界" tabindex="-1">4. Coming soon 的边界 <a class="header-anchor" href="#_4-coming-soon-的边界" aria-label="Permalink to &quot;4. Coming soon 的边界&quot;">​</a></h2><p>Blog 与 Downloads 本轮只是占位：没有文章列表或发布管理，没有下载目录、版本/平台选择、安装包服务、订阅表单或进度承诺。占位页的义务是诚实——说明现在能做什么（回首页、看文档、关注仓库），不虚构文章、日期或发布资产；页面标题与 meta 如实标注状态。后续实现博客或下载时替换占位内容即可，入口路径与导航保持稳定。</p><h2 id="_5-示例展示的归属" tabindex="-1">5. 示例展示的归属 <a class="header-anchor" href="#_5-示例展示的归属" aria-label="Permalink to &quot;5. 示例展示的归属&quot;">​</a></h2><p>Landing 里&quot;参考示例：个人知识库&quot;整段位于 <code>example:knowledge:landing:start/end</code> 标记之间，属于知识库示例的展示内容。标记之外的 Landing 文字只允许链接 Core 章节——删例演练后的 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/scripts/check-docs-build.mjs" target="_blank" rel="noreferrer">docs:build</a> 会对每一处链接做存在性检查，示例专属卡片随标记整块消失，不会留下失效入口。亲手演练一遍：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ui16-drill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ui16-drill</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ui16-drill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 展示段已裁剪，剩余链接全部可解析</span></span></code></pre></div><p>CI 的示例移除任务在每个 PR 上做同样的事，Core-only 站点必须照常构建发布。</p><h2 id="_6-语言、主题与部署" tabindex="-1">6. 语言、主题与部署 <a class="header-anchor" href="#_6-语言、主题与部署" aria-label="Permalink to &quot;6. 语言、主题与部署&quot;">​</a></h2><p>主题偏好由 VitePress 外观切换保存在浏览器本机（<code>localStorage</code>），不跨设备同步；语言只看路径，不承诺跨站自动跟随。部署沿用既有静态链路：GitHub Pages 在 <code>main</code> 上发布（见<a href="./../getting-started/publish-docs">发布教程站点</a>），仓库子路径由 base 承担；自定义 base 用 <code>DOCS_BASE=/your-base/ pnpm docs:build</code> 构建并经内置检查验证——公开站的浏览器旅程（<code>just e2e-docs</code>）包含一次自定义 base 冒烟。</p><h2 id="_7-验证" tabindex="-1">7. 验证 <a class="header-anchor" href="#_7-验证" aria-label="Permalink to &quot;7. 验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 双语契约、成对 meta、链接与片段</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 渲染 + 构建后导航检查（含 base 解析）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e-docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 公开站浏览器旅程：四类入口、CTA、占位页、切换、主题、窄屏、自定义 base</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 主门禁</span></span></code></pre></div><p>对比度沿用文档站点的既定 tokens：正文文字在明暗两种表面都远超 WCAG AA；Landing 自绘的只有卡片旁的小圆点，明暗两种模式下都对背景保持 ≥3:1（非文字元素阈值），深色下的紫色点用更亮的 violet-500 补足。</p><p>公开站的页面类别、导航与渲染器都在 Core：占位页、顶栏与整个渲染链路不出现在任何所有权清单里，删例后照常构建发布。Landing 源文件本身也是 Core 页面，但它在示例所有权清单的 registrationMarkers 里登记了 <code>example:knowledge:landing</code> 标记——示例拥有的不是这个页面，而是标记之间的展示段，删例时随标记整块裁剪；浏览器旅程里与示例相关的只有这一段。</p><hr><p>源码版本：<code>da17f6123c09</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/da17f6123c09fea7fb527b6fcd50f5252112e1ec/docs/tutorials/30-public-site.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,27)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
